$ErrorActionPreference='Stop';$root='/data/ufw-program-candidate-v01/package/UFW-PROGRAM-CANDIDATE-01';$files=@(Get-ChildItem $root -Filter *.ps1)+@(Get-ChildItem $root -Filter *.psm1);if($files.Count -ne 6){throw 'file_count'};foreach($f in $files){$t=$null;$e=$null;[void][Management.Automation.Language.Parser]::ParseFile($f.FullName,[ref]$t,[ref]$e);if($e.Count){throw 'parse'}};Write-Host 'Six package PS files parsed.'